create table public.agency_portal_orgs (id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 1 and 200), industry text not null check(industry in ('home_care','dd_services')), created_at timestamptz not null default now());
create table public.agency_portal_members (org_id uuid not null references public.agency_portal_orgs(id), user_id uuid not null references auth.users(id), role text not null check(role in ('owner','admin','quality_lead')), active boolean not null default true, primary key(org_id,user_id));
create table public.agency_portal_initiatives (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.agency_portal_orgs(id), topic text not null check(length(topic) between 1 and 240), discover text not null default '', dream text not null default '', design text not null default '', destiny text not null default '', measure text not null default '', due_date date, status text not null default 'draft' check(status in ('draft','active','complete')), created_at timestamptz not null default now());
create table public.agency_portal_sponsorships (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.agency_portal_orgs(id), product text not null check(product in ('home_care','dd_services')), status text not null default 'pending' check(status in ('pending','active','expired','revoked')), starts_at timestamptz, ends_at timestamptz, created_at timestamptz not null default now());
alter table public.agency_portal_orgs enable row level security;
alter table public.agency_portal_members enable row level security;
alter table public.agency_portal_initiatives enable row level security;
alter table public.agency_portal_sponsorships enable row level security;
revoke all on public.agency_portal_orgs,public.agency_portal_members,public.agency_portal_initiatives,public.agency_portal_sponsorships from public,anon,authenticated;
grant select on public.agency_portal_orgs,public.agency_portal_members,public.agency_portal_initiatives,public.agency_portal_sponsorships to authenticated;
grant insert (org_id,topic,discover,dream,design,destiny,measure,due_date,status), update(topic,discover,dream,design,destiny,measure,due_date,status) on public.agency_portal_initiatives to authenticated;
grant all on public.agency_portal_orgs,public.agency_portal_members,public.agency_portal_initiatives,public.agency_portal_sponsorships to service_role;
create policy agency_member_self on public.agency_portal_members for select to authenticated using(user_id=(select auth.uid()) and active);
create policy agency_org_read on public.agency_portal_orgs for select to authenticated using(exists(select 1 from public.agency_portal_members m where m.org_id=agency_portal_orgs.id and m.user_id=(select auth.uid()) and m.active));
create policy agency_initiative_read on public.agency_portal_initiatives for select to authenticated using(exists(select 1 from public.agency_portal_members m where m.org_id=agency_portal_initiatives.org_id and m.user_id=(select auth.uid()) and m.active));
create policy agency_initiative_insert on public.agency_portal_initiatives for insert to authenticated with check(exists(select 1 from public.agency_portal_members m where m.org_id=agency_portal_initiatives.org_id and m.user_id=(select auth.uid()) and m.active));
create policy agency_initiative_update on public.agency_portal_initiatives for update to authenticated using(exists(select 1 from public.agency_portal_members m where m.org_id=agency_portal_initiatives.org_id and m.user_id=(select auth.uid()) and m.active)) with check(exists(select 1 from public.agency_portal_members m where m.org_id=agency_portal_initiatives.org_id and m.user_id=(select auth.uid()) and m.active));
create policy agency_sponsorship_read on public.agency_portal_sponsorships for select to authenticated using(exists(select 1 from public.agency_portal_members m where m.org_id=agency_portal_sponsorships.org_id and m.user_id=(select auth.uid()) and m.active and m.role in ('owner','admin')));
create index agency_portal_members_user_idx on public.agency_portal_members(user_id);
create index agency_portal_initiatives_org_idx on public.agency_portal_initiatives(org_id);
create index agency_portal_sponsorships_org_idx on public.agency_portal_sponsorships(org_id);